/* ============================================================================
 * NextWork Theme Studio - painted wallpapers
 *
 * Most scenery in this extension is generated SVG. This file is the exception:
 * raster artwork, carried inline as a data URI because a content script cannot
 * fetch a file - the site's CSP blocks it, and web_accessible_resources would
 * widen the extension's surface for the sake of one picture.
 *
 * Sources live in art/ and are covered by the repository's licence.
 *
 * Inline means the bytes ride in every injected stylesheet, so each image is
 * downscaled and compressed hard, and the audit caps the size.
 *
 * Each image is darkened in two zones, because one global exposure dark enough
 * for body text throws the picture away - the first attempt at this ran the
 * whole frame at 0.17 of source and what reached the page was a smudge.
 *
 * The reading column is a strip down the middle of the viewport; the rest is
 * margin and panels. A scrim over that middle band lets the flanks stay far
 * brighter than a single exposure would ever allow, which on this artwork is
 * the whole game: the composition puts everything worth seeing at the edges.
 *
 *   columnRatio  contrast inside the reading column, floor 7:1   (WCAG AAA)
 *   minRatio     contrast anywhere else,             floor 4.5:1 (WCAG AA)
 *
 * Both are measured on a blurred copy - a reader reads against the local
 * average, not one pixel, which is also what lets the doorway keep a bright
 * core. tools/make-wallpaper.py searches for the brightest exposure that still
 * clears both floors and prints the table it worked from.
 * ==========================================================================*/
(function (root) {
  'use strict';

  root.NWT_WALLPAPERS = {
    /* A concrete arcade at night, looking down the corridor toward a lit
     * doorway. Source: art/concrete-corridor.jpg, 1.95:1 as it stands.
     * Exposure 0.55 with a 0.30 scrim over the middle. */
    concreteCorridor: {
      columnRatio: 7.44,
      minRatio: 4.90,
      sky: '#0c0c0d',
      width: 2560,
      height: 1428,
      uri: 'data:image/webp;base64,'
    }
  };

})(typeof self !== 'undefined' ? self : this);
